import os, re, base64
R = "LockCOC" if os.path.isdir("LockCOC") else "."
def P(p): return os.path.join(R, p)
def rd(p): return open(P(p), encoding="utf-8").read()
def w(p, s): open(P(p), "w", encoding="utf-8").write(s)
def sub(s, old, new, what):
    if old not in s: raise SystemExit("[loi] khong thay doan can sua: " + what)
    return s.replace(old, new, 1)
d = P("static/downloads")
if not os.path.isdir(d): raise SystemExit("[loi] khong thay thu muc static/downloads")
L = rd("templates/landing.html")
if "keynote-hero" in L: raise SystemExit("[loi] da ap dung patch38 roi")
open(os.path.join(d, "demo.mp4"), "wb").write(base64.b64decode(""))
open(os.path.join(d, "demo-poster.jpg"), "wb").write(base64.b64decode(""))
# bo muc video/tab thua (neu da cai patch34/35/37)
L = re.sub(r'\s*<section id="giao-dien".*?</section>\n', "\n", L, flags=re.S)
L = L.replace('\n  <script src="/static/js/tour.js"></script>', "")
L = sub(L, 'aria-label="Video giới thiệu LockCOC: chụp 4-Cuts, đăng bài, xem bảng tin, nhắn tin"', 'aria-label="Video giới thiệu LockCOC: Filter Locket, chụp Đêm, chat, thống kê" data-k="keynote-hero"', "aria")
L = L.replace("Video giới thiệu LockCOC. Ảnh và dữ liệu trong video là mẫu.", "Ảnh và dữ liệu trong video là mẫu.")
L = L.replace("Video quảng cáo LockCOC. Ảnh và dữ liệu trong video là mẫu.", "Ảnh và dữ liệu trong video là mẫu.")
w("templates/landing.html", L)
w("static/landing.css", rd("static/landing.css") + """
/* video keynote 16:9, mep phai mo hoa vao trang */
.phone { width: min(92vw, 440px); }
.phone-in { aspect-ratio: 16 / 9; }
.phone-in video { object-fit: cover;
  -webkit-mask-image: linear-gradient(to right, transparent 0, #000 15%, #000 85%, transparent 100%), linear-gradient(to bottom, transparent 0, #000 22%, #000 78%, transparent 100%);
  -webkit-mask-composite: source-in;
  mask-image: linear-gradient(to right, transparent 0, #000 15%, #000 85%, transparent 100%), linear-gradient(to bottom, transparent 0, #000 22%, #000 78%, transparent 100%);
  mask-composite: intersect; }
.phone-col::before { inset: 10% -8% 10%; }
""")
print("[ok] patch38 xong: thay video giới thiệu bằng bản keynote")
